// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
import { evolvePath } from "@remotion/paths";

const { fontFamily } = loadInter();



export type WellbeingChartProps = Record<string, any>;

const WellbeingChart: React.FC<WellbeingChartProps> = ({
  backgroundColor = "#030712",
  gradientCenterColor = "#0f172a",
  lineGlowColor = "#38bdf8",
  axisColor = "#334155",
  textColor = "#e2e8f0",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Wellbeing",
  yAxisLabel = "Happiness",
  xAxisLabels = ["30", "40", "50", "60", "70"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive Layout Calculations
  const chartWidth = width * 0.6;
  const chartHeight = height * 0.5;
  const leftMargin = (width - chartWidth) / 2;
  const topMargin = (height - chartHeight) / 2 + 50;

  // Animation Timings
  const fadeStart = 15;
  const fadeEnd = 45;
  const drawStart = 45;
  const drawDuration = fps * 3;

  const textFade = interpolate(frame, [fadeStart, fadeEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const drawProgress = interpolate(
    frame,
    [drawStart, drawStart + drawDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.cubic),
    }
  );

  // SVG Path Definition for the U-shaped Curve
  // Starts high, dips low in the middle, and rises high again.
  const pathD = `M 0 ${chartHeight * 0.2} C ${chartWidth * 0.3} ${chartHeight * 1.1} ${chartWidth * 0.7} ${chartHeight * 1.1} ${chartWidth} ${chartHeight * 0.2}`;

  const evolution = evolvePath(drawProgress, pathD);

  // Background style to handle transparency safely
  const bgStyle: React.CSSProperties = transparentBackground
    ? { backgroundColor: `${backgroundColor}00` }
    : {
        background: `radial-gradient(circle at center, ${gradientCenterColor} 0%, ${backgroundColor} 100%)`,
      };

  return (
    <AbsoluteFill style={{ ...bgStyle, fontFamily, color: textColor }}>
      {/* Chart Title */}
      <div
        style={{
          position: "absolute",
          top: height * 0.15,
          width: "100%",
          textAlign: "center",
          fontSize: 48,
          fontWeight: 300,
          opacity: textFade,
          letterSpacing: "0.02em",
          transition: "none",
        }}
      >
        {title}
      </div>

      {/* Y Axis Label */}
      <div
        style={{
          position: "absolute",
          left: leftMargin,
          top: topMargin - 60,
          fontSize: 24,
          fontWeight: 400,
          opacity: textFade,
          color: axisColor,
          transition: "none",
        }}
      >
        {yAxisLabel}
      </div>

      {/* SVG Chart Area */}
      <svg
        style={{
          position: "absolute",
          left: leftMargin,
          top: topMargin,
          width: chartWidth,
          height: chartHeight,
          overflow: "visible",
        }}
      >
        {/* Background Grid */}
        <g opacity={textFade} style={{ transition: "none" }}>
          {/* Vertical Lines */}
          {xAxisLabels.map((_, i) => {
            const x = (chartWidth / (xAxisLabels.length - 1)) * i;
            return (
              <line
                key={`v-${i}`}
                x1={x}
                y1={0}
                x2={x}
                y2={chartHeight}
                stroke={axisColor}
                strokeWidth={1}
                opacity={0.4}
              />
            );
          })}
          
          {/* Horizontal Lines */}
          {[0, 1, 2, 3, 4].map((i) => {
            const y = (chartHeight / 4) * i;
            return (
              <line
                key={`h-${i}`}
                x1={0}
                y1={y}
                x2={chartWidth}
                y2={y}
                stroke={axisColor}
                strokeWidth={1}
                opacity={0.4}
              />
            );
          })}

          {/* Solid Main Axes */}
          <line
            x1={0}
            y1={0}
            x2={0}
            y2={chartHeight + 10}
            stroke={axisColor}
            strokeWidth={2}
          />
          <line
            x1={-10}
            y1={chartHeight}
            x2={chartWidth + 20}
            y2={chartHeight}
            stroke={axisColor}
            strokeWidth={2}
          />
        </g>

        {/* 
          The Animated Curve - Layered for a high quality neon glow effect 
        */}
        
        {/* Outer broad glow */}
        <path
          d={pathD}
          fill="none"
          stroke={lineGlowColor}
          strokeWidth={12}
          strokeLinecap="round"
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
          style={{ filter: "blur(16px)", transition: "none" }}
          opacity={0.5}
        />
        
        {/* Inner tight glow */}
        <path
          d={pathD}
          fill="none"
          stroke={lineGlowColor}
          strokeWidth={6}
          strokeLinecap="round"
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
          style={{ filter: "blur(4px)", transition: "none" }}
          opacity={0.8}
        />
        
        {/* Solid white core line */}
        <path
          d={pathD}
          fill="none"
          stroke="#ffffff"
          strokeWidth={2}
          strokeLinecap="round"
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
          style={{ transition: "none" }}
          opacity={0.9}
        />
      </svg>

      {/* X Axis Labels */}
      <div
        style={{
          position: "absolute",
          left: leftMargin,
          top: topMargin + chartHeight + 20,
          width: chartWidth,
          height: 50,
          opacity: textFade,
          transition: "none",
        }}
      >
        {xAxisLabels.map((label, i) => {
          const x = (chartWidth / (xAxisLabels.length - 1)) * i;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: x - 50,
                width: 100,
                textAlign: "center",
                fontSize: 22,
                color: axisColor,
                fontWeight: 400,
              }}
            >
              {label}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default WellbeingChart;